def fake_ai(prompt):
    text = prompt.lower()
    if "price" in text:
        return "Prices start at $10."
    if "hello" in text:
        return "Hello!"
    return "Sorry, I don't know."

for p in ["Hello", "What is the price?", "Tell me a joke"]:
    print(p, "->", fake_ai(p))

def shout(model, prompt):
    return model(prompt).upper()

def fake_ai(prompt):
    return "thanks for asking"

print(shout(fake_ai, "hi"))

